describe('Form Validation', () => {
    beforeEach(() => {
        cy.visit('/form-page'); // Replace with the actual URL of the form page
    });

    it('should enable the submit button when all required fields are filled', () => {
        cy.get('input[name="firstName"]').type('John');
        cy.get('input[name="lastName"]').type('Doe');
        cy.get('input[name="email"]').type('john.doe@example.com');
        cy.get('input[name="password"]').type('Password123');

        cy.get('button[type="submit"]').should('not.be.disabled');
    });

    it('should keep the submit button disabled when required fields are empty', () => {
        cy.get('input[name="firstName"]').type('John');
        cy.get('input[name="lastName"]').clear(); // Clearing last name to simulate edge case
        cy.get('input[name="email"]').type('john.doe@example.com');
        cy.get('input[name="password"]').type('Password123');

        cy.get('button[type="submit"]').should('be.disabled');
    });
});
